import React, { useState, useEffect } from "react";
import axios from "axios";
import QuestionCard from "./component/QuestionCard";
import "./App.css";

function App() {
  const [questions, setQuestions] = useState([]);
  const [hideAnswers, setHideAnswers] = useState(false);

  // Initialize with 5 empty slots
  const initialFormState = Array(5).fill(null).map(() => ({ 
    question: "", 
    answer: "", 
    confirmAnswer: "" 
  }));

  const [qaList, setQaList] = useState(initialFormState);

  useEffect(() => {
    axios.get("http://localhost:3001/questions")
      .then((res) => setQuestions(res.data))
      .catch((err) => console.error("Error fetching:", err));
  }, []);

  const handleQAChange = (index, field, value) => {
    const updatedList = [...qaList];
    updatedList[index][field] = value;
    setQaList(updatedList);
  };

  const handleSubmit = async () => {
    const allFilled = qaList.every(q => q.question && q.answer && q.confirmAnswer);
    const allMatched = qaList.every(q => q.answer === q.confirmAnswer);

    if (!allFilled) return alert("Please fill all 5 questions.");
    if (!allMatched) return alert("Answers do not match.");

    try {
      await axios.post("http://localhost:3001/responses", { responses: qaList });
      alert("Submitted successfully!");

      // Clear the form after success
      setQaList(initialFormState);
    } catch (err) {
      alert("Submission failed.");
    }
  };

  // Logic to filter out questions already selected in other slots
  const getAvailableQuestions = (currentIndex) => {
    const selectedInOtherSlots = qaList
      .filter((_, idx) => idx !== currentIndex)
      .map(item => item.question);

    return questions.filter(q => {
      const qText = typeof q === 'object' ? q.text : q;
      return !selectedInOtherSlots.includes(qText);
    });
  };

  return (
    <div className="app-container">
      {/* Hide Toggle at the top left */}
      <div className="hide-toggle-container">
        <label>
          <input 
            type="checkbox" 
            checked={hideAnswers} 
            onChange={() => setHideAnswers(!hideAnswers)} 
          />
          Hide Answers
        </label>
      </div>

      <h1 className="app-title">Security Setup</h1>

      <div className="form-wrapper">
        {qaList.map((qa, i) => (
          <QuestionCard
            key={i}
            index={i}
            qa={qa}
            questions={getAvailableQuestions(i)}
            hideAnswers={hideAnswers} 
            onChange={handleQAChange}
          />
        ))}
        <button className="submit-btn" onClick={handleSubmit}>
          Submit All 5 Questions
        </button>
      </div>
    </div>
  );
}

export default App;
